import { getFirestore, collection, addDoc, Timestamp } from "firebase/firestore";
import { getAuth } from "firebase/auth";

const db = getFirestore();
const auth = getAuth();

/**
 * Saves the game history to Firestore
 * 
 * @param {Object} options
 * @param {string} options.result - "Win" | "Loss" | "Draw"
 * @param {string} options.mode - "local" | "online"
 * @param {string|null} [options.opponent] - Opponent's name or UID (optional)
 */
export async function saveGameHistory({ result, mode, opponent = null }) {
  const user = auth.currentUser;
  const userId = user ? user.uid : "guest"; // allow anonymous users

  try {
    await addDoc(collection(db, "gameHistory"), {
      userId,
      date: Timestamp.now(),
      result,
      mode,
      opponent,
    });
    console.log("✅ Game history saved.");
  } catch (error) {
    console.error("❌ Error saving game history:", error);
  }
}

