import React, { useState, useEffect } from "react";
import { auth } from "./firebase";
import { onAuthStateChanged, signOut } from "firebase/auth";
import FirebasePopup from "./components/FirebasePopup";
import { Routes, Route, useParams,useNavigate, Navigate } from "react-router-dom";
import "./App.css";
import AuthPage from "./components/page0.js";
import LocalGame from "./components/LocalGame";
import OnlineGame from "./components/OnlineGame";
import ParticlesBackground from './components/ParticlesBackground';
import UserInfo from './components/UserInfo';

function App() {
  const [user, setUser] = useState(null);
  const [roomCode, setRoomCode] = useState("");
  const [startGame, setStartGame] = useState(false);
  const [showPopup, setShowPopup] = useState(false);
  const [showMultiplayerOptions, setShowMultiplayerOptions] = useState(false);
  const [isRoomCreated, setIsRoomCreated] = useState(false);
  const [createdRoomCode, setCreatedRoomCode] = useState("");

  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (u) => {
      setUser(u);
    });
    return () => unsubscribe();
  }, []);

  const handleSignOut = async () => {
    try {
      await signOut(auth);
      setUser(null);
    } catch (err) {
      console.error("Error signing out:", err);
    }
  };
  function OnlineGameWrapper() {
  const { roomCode } = useParams();
  if (!roomCode) return <Navigate to="/" />;
  return <OnlineGame roomCode={roomCode} />;
}


 return (
  <Routes>
    {/* Email login route */}
    <Route path="/email-login" element={<AuthPage />} />

    {/* Main home route */}
    <Route
      path="/"
      element={
        <div style={{ position: "relative", minHeight: "100vh", overflow: "hidden" }}>
          <ParticlesBackground />
          <div
            style={{
              position: "relative",
              zIndex: 2,
              textAlign: "center",
              paddingTop: "50px",
              color: "#f0f0f0",
            }}
          >
            <h1>Multiplayer Tic-Tac-Toe</h1>

            {!startGame && !showMultiplayerOptions && (
  <>
    <button onClick={() => setShowMultiplayerOptions(true)}>Multiplayer</button>
    <br /><br />
    <button onClick={() => navigate("/local")}>2 Player (Local)</button>
    <br /><br />
    {!user ? (
      <button onClick={() => setShowPopup(true)}>Sign In (includes history)</button>
    ) : (
      <>
        <button onClick={() => navigate("/userinfo")}>Account</button>
        <br /><br />
        <button onClick={handleSignOut}>Sign Out</button>
      </>
    )}
  </>
)}


            {/* Multiplayer Room Options */}
          {showMultiplayerOptions && (
  <>
    <button
      onClick={() => {
        if (!createdRoomCode) {
          const code = Math.random().toString(36).substring(2, 8).toUpperCase();
          setCreatedRoomCode(code);
          setRoomCode(code);
          navigate(`/online/${code}`);
        } else {
          navigate(`/online/${createdRoomCode}`);
        }
        setStartGame(true);
      }}
    >
      Start Game
    </button>

    <br /><br />

    <button
      onClick={() => {
        setShowMultiplayerOptions(false);
        setRoomCode("");
        setCreatedRoomCode("");
        setStartGame(false);
        setShowMultiplayerOptions(false)
      }}
    >
      Back
    </button>
  </>
)}


            {/* Firebase auth popup */}
            {showPopup && <FirebasePopup onClose={() => setShowPopup(false)} />}
          </div>
        </div>
      }
    />

    {/* Dedicated Game Routes */}
    <Route path="/local" element={<LocalGame />} />
    <Route path="/online/:roomCode" element={<OnlineGameWrapper />} />
    <Route path="/userinfo" element={<UserInfo />} />
  </Routes>
);
}

export default App;
