// src/components/FirebasePopup.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { GoogleAuthProvider, signInWithPopup } from "firebase/auth";
import "./styles.css";
import { auth } from "../firebase";


const provider = new GoogleAuthProvider();

export default function FirebasePopup({ onClose }) {
  const [showPopup, setShowPopup] = useState(true);
  const navigate = useNavigate();

  const handleGoogleSignIn = async () => {
    try {
      await signInWithPopup(auth, provider);
      alert(`Welcome, ${auth.currentUser.displayName}`);
      setShowPopup(false);
      onClose(); // Notify App to proceed to room input
    } catch (error) {
      console.error("Google Sign-In Error:", error);
      alert("Error during Google Sign-In");
    }
  };

  const handleEmailSignIn = () => {
    setShowPopup(false);
    navigate("/email-login"); // Route to email login component
  };

  return (
    <>
{showPopup && (
  <div className="popup-wrapper">
    <div className="login form">
      <header>Get Started</header>

      <input
        type="button"
        className="button"
        value="Continue with Google"
        onClick={handleGoogleSignIn}
      />

      <input
        type="button"
        className="button"
        value="Continue with Email"
        onClick={handleEmailSignIn}
      />

      <input
        type="button"
        className="redirect"
        value="Close"
        onClick={() => {
          setShowPopup(false);
          onClose();
        }}
      />
    </div>
  </div>
)}

    </>
  );
}
