import React, { useEffect, useState } from 'react';
import './UserInfo.css';
import { initializeApp, getApps } from 'firebase/app';
import { getAuth, onAuthStateChanged } from 'firebase/auth';
import { getFirestore, collection, getDocs } from 'firebase/firestore';
import ParticlesBackground from './ParticlesBackground';
import { useNavigate } from "react-router-dom";

// Firebase config
const firebaseConfig = {
  apiKey: "AIzaSyAqF5MOmgFICyWKaBgj2DKN7B7He5VFwKc",
  authDomain: "plannet-ae327.firebaseapp.com",
  projectId: "plannet-ae327",
  storageBucket: "plannet-ae327.firebasestorage.app",
  messagingSenderId: "794674013856",
  appId: "1:794674013856:web:2eb1fe687df4eded6acbc5",
  measurementId: "G-J2Y1QJ6GVS"
};

// Initialize Firebase only if not already initialized
const app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0];
const auth = getAuth(app);
const db = getFirestore(app);

const UserInfo = () => {
  const [user, setUser] = useState(null);
  const [gameHistory, setGameHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);

      if (currentUser) {
        try {
          const gamesRef = collection(db, 'users', currentUser.uid, 'games');
          const gamesSnapshot = await getDocs(gamesRef);
          const games = gamesSnapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));

          // Sort by timestamp descending (newest first)
          games.sort((a, b) => {
            const t1 = a.timestamp?.toMillis?.() || 0;
            const t2 = b.timestamp?.toMillis?.() || 0;
            return t2 - t1;
          });

          setGameHistory(games);
        } catch (err) {
          console.error("Error fetching game history:", err);
        }
      }

      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return (
    <div style={{ position: "relative", minHeight: "100vh", overflow: "hidden" }}>
      <ParticlesBackground />

      <div style={{ position: "relative", zIndex: 2, textAlign: "center", paddingTop: "60px", color: "#f0f0f0" }}>
        <div className="container" style={{ maxWidth: "600px", margin: "0 auto" }}>
          <h1>User Info</h1>

          <div id="user-info" style={{ marginBottom: "40px" }}>
            {user ? (
              <>
                <p><strong>User ID:</strong> {user.uid}</p>
                <p><strong>Email:</strong> {user.email}</p>
                <p><strong>Display Name:</strong> {user.displayName || 'N/A'}</p>
              </>
            ) : (
              <p>No user is signed in.</p>
            )}
          </div>

          <hr style={{ borderColor: "#aaa", margin: "30px 0" }} />

          <div className="game-history">
            <h2>Game History</h2>
            {loading ? (
              <p>Loading...</p>
            ) : user ? (
              gameHistory.length > 0 ? (
                <ul style={{ textAlign: "left", padding: "0 20px" }}>
                  {gameHistory.map((game, index) => (
                    <li key={game.id || index} style={{ marginBottom: "15px", background: "#2c2f36", padding: "10px", borderRadius: "8px" }}>
                      <p><strong>Room Code:</strong> {game.roomCode || 'Unknown'}</p>
                      <p><strong>Winner:</strong> {game.winner || 'Undecided'}</p>
                      <p><strong>Date:</strong> {game.timestamp?.toDate?.().toLocaleString() || 'Unknown'}</p>
                    </li>
                  ))}
                </ul>
              ) : (
                <p>No games played yet.</p>
              )
            ) : (
              <p>Please log in to see your game history.</p>
            )}
          </div>

          <div style={{ marginTop: "50px" }}>
            <button 
              onClick={() => navigate("/")} 
              style={{
                backgroundColor: "#007bff",
                color: "#fff",
                border: "none",
                padding: "10px 20px",
                borderRadius: "5px",
                cursor: "pointer"
              }}
            >
              ← Back to Homepage
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserInfo;
