import React from 'react';
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';

const ParticlesBackground = () => {
  const particlesInit = async (engine) => {
    await loadSlim(engine); // use slim version instead of full
  };

  return (
    <div style={{ 
      position: 'absolute', 
      top: 0, 
      left: 0, 
      width: '100%', 
      height: '100%', 
      zIndex: -1, 
      pointerEvents: 'none' // optional: let clicks pass through
    }}>
      <Particles
        id="tsparticles"
        init={particlesInit}
        options={{
          fullScreen: { enable: false }, // prevent hijacking full screen
          background: {
            color: { value: "#000000" }
          },
          particles: {
            number: {
              value: 50,
              density: { enable: true, area: 800 }
            },
            color: { value: "#ffffff" },
            size: { value: 3 },
            move: { enable: true, speed: 1 },
            links: {
              enable: true,
              color: "#ffffff",
              distance: 150,
              opacity: 0.4,
              width: 1
            }
          }
        }}
      />
    </div>
  );
};

export default ParticlesBackground;
